# Try with objdump to find the actual function names for those addresses
# Use nm or objdump to find nearest symbol
aarch64-linux-gnu-objdump -t /tmp/symbols/libmonosgen-2.0.so.dbg 2>/dev/null | grep -v "^$" | awk '{print $1, $NF}' | sort | awk -v a1="00000000002f4b20" -v a2="00000000002f4c84" -v a3="00000000002c1a40" '
BEGIN{} {if ($1 <= a1) {n1=$2; s1=$1} if ($1 <= a2) {n2=$2; s2=$1} if ($1 <= a3) {n3=$2; s3=$1}} END{print a1": "n1" (+"a1-s1")"; print a2": "n2" (+"a2-s2")"; print a3": "n3" (+"a3-s3")}' 2>/dev/null || true

# Alternative: use nm to find nearest symbols
nm -C /tmp/symbols/libmonosgen-2.0.so.dbg 2>/dev/null | sort | awk '
/^[0-9a-f]/ {addrs[NR]=$1; names[NR]=$3; count=NR}
END {
  targets["2f4b20"]=1; targets["2f4c84"]=1; targets["2c1a40"]=1
  for (t in targets) {
    best=""
    for (i=1;i<=count;i++) {
      if (addrs[i] <= t) best=names[i]" + 0x"sprintf("%x", strtonum("0x"t) - strtonum("0x"addrs[i]))
    }
    print "0x"t": "best
  }
}' 2>/dev/null || true

